// Elektronik zar: düğmeye basınca 7 segment göstergede 1-6 arası sayı çıkar.
const int SEGMENT_PINLERI[7] = {2, 3, 4, 5, 6, 7, 8};  // A, B, C, D, E, F, G
const int BUTON_PIN = 12;
const bool ORTAK_ANOT = false;   // Ortak anotlu gösterge için true yap (COM -> 5V).
const int ANIMASYON_ADIMI = 15;  // dönen rakam sayısı
const int ILK_BEKLEME = 30;      // ms; ilk adımın süresi
const int BEKLEME_ARTISI = 10;   // ms; her adımda yavaşlama

// Rakamların segmentleri: bit 0 = A ... bit 6 = G.
const byte RAKAMLAR[7] = {
  0b0111111,  // 0
  0b0000110,  // 1
  0b1011011,  // 2
  0b1001111,  // 3
  0b1100110,  // 4
  0b1101101,  // 5
  0b1111101,  // 6
};
const byte CIZGI = 0b1000000;  // yalnız G: "-"

bool tohumAtildi = false;

void goster(byte desen) {
  for (int i = 0; i < 7; i++) {
    bool yan = desen & (1 << i);
    // Ortak katotta HIGH yakar; ortak anotta LOW yakar.
    digitalWrite(SEGMENT_PINLERI[i], yan != ORTAK_ANOT ? HIGH : LOW);
  }
}

// Rakamları giderek yavaşlayarak döndürür; son gösterileni döndürür.
int zarAt() {
  int sayi = 0;
  for (int i = 0; i < ANIMASYON_ADIMI; i++) {
    int yeni;
    do {
      yeni = random(1, 7);  // 1-6
    } while (yeni == sayi);  // aynı rakam art arda gelmesin
    sayi = yeni;
    goster(RAKAMLAR[sayi]);
    delay(ILK_BEKLEME + i * BEKLEME_ARTISI);
  }
  return sayi;
}

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 7; i++) pinMode(SEGMENT_PINLERI[i], OUTPUT);
  pinMode(BUTON_PIN, INPUT_PULLUP);
  goster(CIZGI);
}

void loop() {
  if (digitalRead(BUTON_PIN) != LOW) return;
  delay(30);  // buton titreşimi
  if (digitalRead(BUTON_PIN) != LOW) return;

  // İlk basış anı her seferinde farklıdır; rastgeleliğin tohumu olur.
  if (!tohumAtildi) {
    randomSeed(micros());
    tohumAtildi = true;
  }

  int sayi = zarAt();
  Serial.print("Zar: ");
  Serial.println(sayi);

  // Bırakılana kadar bekle.
  while (digitalRead(BUTON_PIN) == LOW) delay(10);
  delay(30);
}
